import { hb } from './build';
import type { Lesson, T, Unit, VisualSpec } from './types';

type R = readonly [string, string];

function L(
  id: string,
  topic: Lesson['topic'],
  minutes: number,
  title: R,
  situation: R,
  explain: R[],
  visual: VisualSpec | undefined,
  caption: R | undefined,
  example: { setup: R; reasoning: R },
  questionIds: string[],
  task: R,
  recap: R[],
  sources: Lesson['sources'],
): Lesson {
  return { id, topic, minutes, title, situation, explain, visual, visualCaption: caption, example, questionIds, task, recap, sources };
}

